#include <bits/stdc++.h>using namespace std;#define int long long#define go(i,a,b) for(int i=a;i<=b;i++)#define og(i,a,b) for(int i=b;i>=a;i--) const int mod = 676767677;int T,n,a[100005],pre[100005],suf[100005];char s[100005]; bool build(char c){    s[1] = c;    go(i,1,n-1){        int d = a[i + 1] - a[i];        if(d == 1){            if(s[i] != 'L') return 0;            s[i + 1] = 'L';        }        else if(d == -1){            if(s[i] != 'R') return 0;            s[i + 1] = 'R';        }        else{            s[i + 1] = (s[i] == 'L' ? 'R' : 'L');        }    }    pre[0] = 0;    go(i,1,n) pre[i] = pre[i - 1] + (s[i] == 'L');    suf[n + 1] = 0;    og(i,1,n) suf[i] = suf[i + 1] + (s[i] == 'R');    go(i,1,n){        if(pre[i] + suf[i] != a[i]) return 0;    }    return 1;} void O_o(){    cin >> n;    go(i,1,n) cin >> a[i];    go(i,1,n-1){        if(abs(a[i + 1] - a[i]) > 1){            cout << 0 << '\n';            return;        }    }    int ans = 0;    ans += build('L');    ans += build('R');    cout << ans % mod << '\n';} signed main(){    ios::sync_with_stdio(false);    cin.tie(nullptr); cout.tie(nullptr);    cin >> T;    while(T--) O_o();}